              <div className="flex-1 min-w-0">
                <p className="text-xs font-bold text-gray-500 mb-0.5">UPI ID</p>
                <p className="font-mono text-sm font-semibold text-gray-900 break-all">{upiScreen.upiId}</p>
              </div>
              <button
                onClick={() => {
